package com.order.menu.module.entertainment.mode.naval;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import com.order.menu.module.entertainment.mode.naval.NavalState.*;
import java.util.*;
class NavalDepthChargeTest {
 final NavalMilitaryTest f=new NavalMilitaryTest();
 Action attack(){return f.action("d","depthCharge",4,6);}
 @Test void pricesAndIndependentLaunchers(){assertEquals(25,NavalMilitary.MODELS.get("depthCharge")[2]);assertEquals(25,NavalMilitary.MODELS.get("cruiser")[2]);assertEquals(50,NavalMilitary.MODELS.get("submarine")[2]);assertEquals(20,NavalMilitary.MODELS.get("radar")[2]);assertEquals(20,NavalMilitary.MODELS.get("jammer")[2]);
  for(int rotation:List.of(0,90,180,270))for(int lost:List.of(0,1)){Ship d=f.ship("depthCharge","d",0,0);d.rotation=rotation;d.w=rotation%180==0?1:2;d.h=rotation%180==0?2:1;d.hits.add(NavalMilitary.key(NavalMilitary.parts(d).get(lost).cell()));NavalState s=f.battle(List.of(d,f.ship("cruiser","a",4,0)),List.of(f.ship("cruiser","e",9,9)));NavalEngine.attack(s,0,attack(),0);Event e=s.events.get(0);assertFalse(e.destroyed());assertEquals(1,e.torpedoes().size());assertEquals(lost==0?7:5,e.cells().get(0).y());assertTrue(s.players.get(1).shots.stream().noneMatch(c->c.y()==6));}}
 @Test void successfulVoyageAttacksTwoCellsWithoutMarkingTravel(){NavalState s=f.battle(List.of(f.ship("depthCharge","d",0,0)),List.of(f.ship("cruiser","e",9,9)));NavalEngine.attack(s,0,attack(),0);Event e=s.events.get(0);assertFalse(e.destroyed());assertEquals(2,e.cells().size());assertEquals(2,e.torpedoes().size());assertEquals(new Cell(4,6),e.route().get(e.route().size()-1));assertTrue(s.players.get(1).shots.stream().noneMatch(c->c.y()==6));}
 @Test void collisionSinksBothEntireHullsAndImpactsCurrentWater(){NavalState s=f.battle(List.of(f.ship("depthCharge","d",0,0),f.ship("cruiser","a",3,0)),List.of(f.ship("cruiser","target",4,5),f.ship("cruiser","reserve",9,9)));Action a=attack();a.x=8;NavalEngine.attack(s,0,a,0);Event e=s.events.get(0);assertTrue(e.destroyed());assertEquals(2,s.players.get(0).ships.get(0).hits.size());assertEquals(3,s.players.get(1).ships.get(0).hits.size());assertEquals(new Cell(3,6),e.route().get(e.route().size()-1));assertTrue(e.cells().stream().anyMatch(c->c.x()==3&&c.y()==6&&c.result().equals("miss")));assertTrue(e.cells().stream().noneMatch(c->c.x()<3&&c.y()==6));assertEquals(2,e.backfire().size());}
 @Test void mineBlastIsTwoCellsAtActualCollision(){NavalState s=f.battle(List.of(f.ship("depthCharge","d",0,0),f.ship("cruiser","a",3,0)),List.of(f.ship("cruiser","e",9,9)));s.players.get(1).mines.add(new Cell(2,6));Action a=attack();a.x=8;NavalEngine.attack(s,0,a,0);assertTrue(s.events.get(0).destroyed());assertEquals(2,s.events.get(0).cells().size());assertTrue(s.players.get(1).mines.isEmpty());assertEquals(2,s.players.get(0).ships.get(0).hits.size());assertTrue(s.events.get(0).cells().stream().allMatch(c->c.x()==1||c.x()==2));}
}
